/* #region Reset */
html,
body {
    margin: 0;
    padding: 0;
}

button {
    text-align: left; /* fallback */
    text-align: start;
}

::-moz-placeholder {
    margin: 0;
    padding: 0;
    font: inherit;
    font-size: 1em;
}

::placeholder,
a,
blockquote,
button,
cite,
code,
dd,
dl,
figure,
input,
kbd,
ol,
optgroup,
pre,
samp,
select,
small,
td,
textarea,
th,
ul {
    margin: 0;
    padding: 0;
    font: inherit;
    font-size: 1em;
}

.page-title,
h1,
h2,
h3,
h4,
h5,
h6,
.h7,
.h8,
.h9,
.h10 {
    margin: 0;
    font: inherit;
    font-size: 1em;
}

td,
th {
    vertical-align: top;
}

p {
    margin: 0;
}

embed,
iframe,
img,
object,
picture,
svg,
video {
    --display: block;
    display: block;
    display: var(--display, block);
    max-width: 100%;
}

img {
    width: auto;
    height: auto;
    -o-object-fit: cover;
    object-fit: cover;
}

hr {
    margin: 0;
    border: none;
    border-top: currentColor solid 1px;
    border-bottom: currentColor solid 1px;
}

input,
label,
pre,
pre > code {
    --display: block;
    display: block;
    display: var(--display, block);
}

*,
::before,
::after {
    box-sizing: border-box;
}

html {
    -moz-text-size-adjust: none;
    -webkit-text-size-adjust: none;
    text-size-adjust: none;
    -moz-osx-font-smoothing: grayscale;
    -webkit-font-smoothing: antialiased;
    color-scheme: light dark;
}
html[data-brightness-mode="light"] {
    color-scheme: light;
    color-scheme: only light;
}

html[data-brightness-mode="dark"] {
    color-scheme: dark;
    color-scheme: only dark;
}

